with recent_web_events as (select * from web_events where duration_sec = 216 and hour(event_time) between 10 and 15 and page is not null), summary as (select hour(event_time) as event_hour, sort_array(collect_set(page)) as page_list, count(duration_sec) as duration_sec_count from recent_web_events group by hour(event_time)) select * from summary where duration_sec_count > 6 order by duration_sec_count desc, event_hour limit 10;
